    addQ(2, 9, 2, 'Türkiye\'de peri bacalarının (Kapadokya) oluşumunda iç kuvvet olarak volkanizma, dış kuvvet olarak hangisi etkilidir?', 'Akarsu ve sel suları aşındırması', 'Buzullar', 'Rüzgar biriktirmesi', 'Dalgalar', 'Heyelan', 'A', 'Volkanik tüf ve bazaltları akarsu ve sel suları aşındırır, rüzgar ise ikincil etkiye sahiptir.');
    addQ(2, 9, 2, 'Kuzey Anadolu Fay Hattı (KAF) nereden başlar ve nerede son bulur?', 'Saros Körfezi\'nden başlar - Van Gölü kuzeyi ve Aras Vadisi\'ne kadar uzanır', 'İskenderun\'dan başlar - Sinop\'a uzanır', 'İzmir\'den başlar - Hakkari\'ye uzanır', 'Antalya\'dan - Trabzon\'a', 'Mersin\'den - Artvin\'e', 'A', 'KAF Saros Körfezi, Marmara Denizi, Bolu, Tokat, Erzincan üzerinden Doğu Anadolu\'ya uzanan doğrultu atımlı tehlikeli bir faydır.');
    addQ(2, 9, 2, 'Türkiye\'de dağların kıyıya paralel uzandığı Karadeniz ve Akdeniz\'de görülen kıyı tipi hangisidir?', 'Boyuna Kıyı Tipi', 'Enine Kıyı Tipi', 'Ria Kıyı Tipi', 'Dalmaçya Kıyı Tipi', 'Kalanklı Kıyı Tipi', 'A', 'Dağların kıyıya paralel uzandığı yerlerde boyuna kıyı tipi görülür, falezler (yalıyar) çoktur.');

    // Level 3: Zor & Detay
    addQ(2, 9, 3, 'İstanbul Boğazı, Çanakkale Boğazı ve Haliç hangi kıyı tipine en güzel örnektir?', 'Ria Kıyı Tipi', 'Dalmaçya Kıyı Tipi', 'Fiyort Kıyı Tipi', 'Haff Kıyı Tipi', 'Limanlı Kıyı Tipi', 'A', 'Eski akarsu vadilerinin deniz suları altında kalmasıyla oluşan boğulmuş vadilere Ria tipi kıyı denir.');
    addQ(2, 9, 3, 'Antalya Kaş kıyılarında denize paralel uzanan adacıkların oluşturduğu kıyı tipi hangisidir?', 'Dalmaçya Kıyı Tipi', 'Boyuna', 'Enine', 'Ria', 'Watt', 'A', 'Adriyatik Denizi\'ndeki gibi kıyıya paralel dağların sular altında kalması Dalmaçya kıyı tipidir.');
    addQ(2, 9, 3, 'Türkiye kıyılarında Fiyort ve Skyer tipi kıyıların görülmemesinin temel sebebi nedir?', 'Matematik konum (Kutup kuşağında olmamamız, buzulların deniz seviyesine inmemesi)', 'Özel konum', 'Gelgit genliğinin az olması', 'Dağların uzanışı', 'Akarsuların rejimleri', 'A', 'Fiyort ve Skyer buzulların deniz seviyesine indiği yüksek enlemlerde (Norveç, Kanada) görülür.');
    addQ(2, 9, 3, 'Türkiye\'de gelgit genliğinin az olması nedeniyle okyanus kıyılarında görülen Haliç ve Watt tipi kıyılar neden görülmez?', 'İç deniz ülkesi olması ve okyanusa doğrudan kıyısı bulunmaması', 'Yükseltinin fazla olması', 'Sıcak su akıntıları', 'Tuzluluk oranı', 'Boğazların varlığı', 'A', 'İç denizlerde gelgit genliği birkaç santimetredir; okyanuslardaki gibi devasa gelgit deltaları yıkıp haliç oluşturamaz.');
    addQ(2, 9, 3, 'Yeraltı suyunun kalker tabakasını eritmesiyle oluşan mağara tavanlarının çökmesi sonucu oluşan derin doğal kuyulara ne denir?', 'Obruk', 'Dolin', 'Uvala', 'Polye', 'Lapya', 'A', 'Konya Ovası ve Cennet-Cehennem çökükleri tipik obruk oluşumlarıdır.');
    addQ(2, 9, 3, 'Karstik aşınım şekillerinin en büyüğü olan ve içinde yerleşim kurulan karstik ovalara (Tefenni, Acıpayam, Korkuteli, Muğla, Elmalı - TAKKE) ne ad verilir?', 'Polye', 'Uvala', 'Dolin', 'Lapya', 'Kör Vadi', 'A', 'Polyeler karstik çöküntü alanları olup verimli karstik ovaları oluştururlar.');
    addQ(2, 9, 3, 'Türkiye\'de rüzgar erozyonunun en şiddetli olduğu yerleşim yerlerinden biri olan ve rüzgar erozyonunu önleme sahası bulunan ilçe hangisidir?', 'Konya - Karapınar', 'Şanlıurfa - Siverek', 'Iğdır - Aralık', 'Ankara - Polatlı', 'Nevşehir - Ürgüp', 'A', 'Karapınar Türkiye\'de rüzgar kumullarının ve çölleşme tehlikesinin en belirgin olduğu yerdir.');
    addQ(2, 9, 3, 'Büyük Menderes ve Gediz nehirlerinin yatak eğiminin azalması sonucu oluşturduğu kıvrımlı akarsu şekillerine ne ad verilir?', 'Menderes', 'Kanyon Vadi', 'Çentik Vadi', 'Dev Kazanı', 'Taraça', 'A', 'Menderes hem aşındırma hem biriktirme şeklidir, akarsuyun boyu uzar ve akış hızı azalır.');
    addQ(2, 9, 3, 'Manavgat, Düden ve Kurşunlu şelalelerinin döküldükleri yerde oluşturdukları derin çukurlara ne denir?', 'Dev Kazanı', 'Kanyon', 'Menderes', 'Sirk', 'Traverten', 'A', 'Çağlayanların tabanında suyun çarparak oyduğu çukurluklara dev kazanı denir.');
    addQ(2, 9, 3, 'Denizli Pamukkale\'de kalsiyum bikarbonatlı termal suların yüzeye çıkıp karbondioksitin uçmasıyla çökelen basamaklı beyaz kalker yapılarına ne denir?', 'Traverten', 'Sarkıt', 'Dikit', 'Sütun', 'Lapya', 'A', 'Pamukkale travertenleri kimyasal tortul / karstik biriktirme şeklidir.');

