    // Level 1: Temel İklim
    addQ(2, 10, 1, 'Türkiye\'de yıllık yağış miktarının en fazla olduğu ilimiz aşağıdakilerden hangisidir?', 'Rize', 'Trabzon', 'Antalya', 'Muğla', 'Zonguldak', 'A', 'Rize yıllık 2400 mm\'yi aşan yağışıyla Türkiye\'nin en çok yağış alan ilidir.');
    addQ(2, 10, 1, 'Türkiye\'de yıllık yağış miktarının en az olduğu bölgemiz ve çevresi neresidir?', 'İç Anadolu (Tuz Gölü çevresi ve Konya Kapalı Havzası)', 'Güneydoğu Anadolu', 'Doğu Anadolu', 'Marmara', 'Ege', 'A', 'Etrafı dağlarla çevrili olduğu için nemli hava kütlelerinin giremediği Tuz Gölü çevresi en az yağış alan yerdir.');
    addQ(2, 10, 1, 'Akdeniz ikliminin tipik doğal bitki örtüsü aşağıdakilerden hangisidir?', 'Maki', 'Bozkır (Step)', 'Geniş yapraklı orman', 'Çayır', 'Tundra', 'A', 'Akdeniz ikliminde yaz kuraklığına dayanıklı bodur ağaççıklardan oluşan makiler hakimdir.');
    addQ(2, 10, 1, 'İç Anadolu ve Güneydoğu Anadolu\'da ilkbahar yağışlarıyla yeşeren, yazın kuruyan otsu bitkilerden oluşan bitki örtüsü nedir?', 'Bozkır (Step)', 'Maki', 'Savan', 'Tayga', 'Çayır', 'A', 'Karasal iklimin doğal bitki örtüsü bozkırdır (yavşan otu, geven, gelincik).');
    addQ(2, 10, 1, 'Türkiye\'yi kuzeybatıdan etkileyen, kışın soğuk ve kar yağışı getiren rüzgar hangisidir?', 'Karayel', 'Yıldız', 'Poyraz', 'Lodos', 'Samyeli', 'A', 'Kayıp Sakal şifresiyle: Karayel (KB), Yıldız (K), Poyraz (KD), Samyeli (GD), Kıble (G), Lodos (GB).');
    addQ(2, 10, 1, 'Güneybatıdan esen, ılık ve nemli hava getiren, kışın soba zehirlenmelerine yol açabilen rüzgar hangisidir?', 'Lodos', 'Poyraz', 'Karayel', 'Yıldız', 'Günbatısı', 'A', 'Lodos sıcak ve nemlidir, kışın karları hızla eritip su baskınlarına ve baca gazı zehirlenmelerine neden olabilir.');
    addQ(2, 10, 1, 'Doğu Karadeniz\'de dağları aşıp Rize ve Çoruh vadisine inen havanın sürtünmeyle ısınıp kurutucu etki yapması olayına ne denir?', 'Föhn rüzgarı', 'Etezien', 'Meltem', 'Bora', 'Mistral', 'A', 'Föhn rüzgarı dağdan aşağı inerken her 100 metrede 1°C ısınır; Rize\'de turunçgil yetişmesini sağlar.');
    addQ(2, 10, 1, 'Ilıman karasal iklimde ilkbaharda ısınan havanın yükselerek soğumasıyla oluşan "kırkikindi" yağışlarının türü nedir?', 'Konveksiyonel (Yükselim) Yağışları', 'Orografik (Yamaç) Yağışları', 'Cephe (Frontal) Yağışları', 'Siklonik Yağışlar', 'Muson Yağışları', 'A', 'İç Anadolu\'da ilkbahar aylarında öğleden sonra görülen yağışlar konveksiyoneldir.');
    addQ(2, 10, 1, 'Karadeniz dağlarının denize bakan yamaçlarında nemli hava kütlesinin dağ boyunca yükselip soğumasıyla oluşan yağış türü nedir?', 'Orografik (Yamaç) Yağışları', 'Konveksiyonel Yağışlar', 'Cephe Yağışları', 'Dinamik Yağışlar', 'Suni Yağışlar', 'A', 'Dağların kıyıya paralel uzandığı Doğu ve Batı Karadeniz ile Toroslar\'da orografik yağışlar yaygındır.');
    addQ(2, 10, 1, 'Türkiye\'de kış mevsiminde görülen yağışların büyük bir kısmını oluşturan, sıcak ve soğuk hava kütlelerinin karşılaşma alanlarında oluşan yağış hangisidir?', 'Cephe (Frontal) Yağışları', 'Yükselim Yağışları', 'Yamaç Yağışları', 'Tropikal Yağışlar', 'Konveksiyonel', 'A', 'Türkiye orta kuşakta yer aldığı için kutup havası ile tropikal havanın çarpışmasıyla cephe yağışları oluşur.');

    // Level 2: Orta Düzey
    addQ(2, 10, 2, 'Rize ve çevresinde turunçgil, Artvin Çoruh vadisinde zeytin, Alanya-Gazipaşa kıyılarında muz yetişmesi neyin göstergesidir?', 'Mikroklima (Dar alanlı özel iklim) alanı olmalarının', 'Geniş Akdeniz iklim bölgesinde olmalarının', 'Topraklarının aynı olmasının', 'Ekvatoral iklim yaşandığının', 'Tarımsal sulamanın', 'A', 'Çevrelerinden farklı özel iklim şartları gösteren dar alanlara mikroklima denir.');
    addQ(2, 10, 2, 'Kışın Sibirya Termik Yüksek Basıncı Türkiye\'yi etkisi altına aldığında ülkemizde hava nasıl olur?', 'Aşırı soğuk, ayaz, kar yağışlı ve durgun', 'Ilık ve yağmurlu', 'Sıcak ve kurak', 'Fırtınalı ve sisli', 'Sürekli sağanak yağışlı', 'A', 'Sibirya yüksek basıncı özellikle Doğu Anadolu ve İç Anadolu\'da kışın şiddetli ayaz ve dondurucu soğuk yapar.');
    addQ(2, 10, 2, 'Yazın Güneydoğu Anadolu Bölgesi\'nde sıcaklıkların ve buharlaşmanın aşırı yüksek olmasında etkili olan dinamik basınç merkezi hangisidir?', 'Basra Termik Alçak Basıncı', 'Asor Yüksek Basıncı', 'İzlanda Alçak Basıncı', 'Sibirya Yüksek Basıncı', 'Muson Alçak Basıncı', 'A', 'Basra Basıncı güneyden sıcak çöl havasını ülkemize taşıyarak Güneydoğu\'da kavurucu sıcaklık yapar.');
    addQ(2, 10, 2, 'Aşağıdaki bitki türlerinden hangisi "endemik" (dünyada yalnızca belirli bir yöreye özgü) bitkilerimize örnektir?', 'Köyceğiz Sığla (Günlük) Ağacı, Datça Hurması, Kazdağı Göknarı', 'Kızılçam', 'Meşe', 'Kavak', 'Söğüt', 'A', 'Muğla Köyceğiz\'deki Sığla ağacı relikt ve endemik bir türdür, eczacılıkta kullanılır.');
    addQ(2, 10, 2, 'Karadeniz ormanlarının tahrip edilmesiyle oluşan yalancı maki topluluklarına ne ad verilir?', 'Psödomaki', 'Garig', 'Antropojen Bozkır', 'Çayır', 'Maki', 'A', 'Karadeniz\'de ormanların yok edilmesiyle oluşan fındık, şimşir, böğürtlen gibi çalılara psödomaki denir.');
    addQ(2, 10, 2, 'İç Anadolu\'da insanların meşe ormanlarını tahrip etmesi sonucu ortaya çıkan bozkırlara ne denir?', 'Antropojen Bozkır', 'Doğal Bozkır', 'Maki', 'Garig', 'Tundra', 'A', 'İnsan müdahalesiyle açılan bozkırlara antropojen bozkır denir.');
    addQ(2, 10, 2, 'Marmara Bölgesi\'nde Karadeniz, Akdeniz ve Karasal iklimlerin bir arada görülmesi bölgeye hangi avantajı sağlamıştır?', 'Bitki örtüsü ve tarım ürünü çeşitliliğinin en fazla olduğu bölge olmasını', 'Yıllık yağışın en çok olduğu bölge olmasını', 'Yükseltinin en fazla olmasını', 'Buzul şekillerinin çok olmasını', 'Sıcak su kaynaklarının olmamasını', 'A', 'Marmara bir geçiş bölgesidir ve iklim çeşitliliği sayesinde çok farklı tarım ürünleri bir arada yetiştirilebilir.');
    addQ(2, 10, 2, 'Türkiye\'de bağıl nemin (nem oranının) yıl boyunca en yüksek olduğu bölge hangisidir?', 'Karadeniz Bölgesi (Özellikle Doğu Karadeniz)', 'Güneydoğu Anadolu', 'İç Anadolu', 'Doğu Anadolu', 'Ege', 'A', 'Yağış ve bulutluluğun en fazla olduğu Karadeniz\'de bağıl nem daima yüksektir, sıcaklık farkları azdır.');
    addQ(2, 10, 2, 'Türkiye\'de günlük ve yıllık sıcaklık farklarının en fazla olduğu bölge hangisidir?', 'Doğu Anadolu Bölgesi', 'Akdeniz Bölgesi', 'Karadeniz Bölgesi', 'Ege Bölgesi', 'Marmara Bölgesi', 'A', 'Nem azlığı (şiddetli karasallık) ve yüksek irtifa nedeniyle Doğu Anadolu\'da sıcaklık farkları çok büyüktür.');
    addQ(2, 10, 2, 'Ege kıyılarında yaz aylarında deniz ile kara arasındaki sıcaklık farkından doğan yerel rüzgara (deniz meltemi) halk arasında ne ad verilir?', 'İmbat', 'Lodos', 'Poyraz', 'Etezien', 'Keşişleme', 'A', 'İzmir ve Ege kıyılarında öğleden sonra denizden karaya esen serinletici melteme İmbat denir.');

    // Level 3: Zor & Detay
    addQ(2, 10, 3, 'Türkiye\'de orman yangını riskinin en yüksek olduğu bölgeler sırasıyla hangileridir?', 'Akdeniz ve Ege Bölgeleri', 'Karadeniz ve Marmara', 'İç Anadolu ve Doğu Anadolu', 'Güneydoğu Anadolu', 'Trakya', 'A', 'Yaz kuraklığının şiddetli olması, yüksek sıcaklık ve kızılçam varlığı nedeniyle Akdeniz ve Ege\'de yangın riski zirvededir.');
    addQ(2, 10, 3, 'Türkiye\'de ormanların deniz seviyesinden başlama sınırı (orman alt sınırı) en alçak olan bölge neresidir?', 'Karadeniz Bölgesi (0 metre)', 'Akdeniz Bölgesi', 'Ege Bölgesi', 'Marmara Bölgesi', 'İç Anadolu', 'A', 'Nem ve yağış yeterli olduğu için Karadeniz\'de ormanlar doğrudan deniz kıyısından (0 metreden) başlar.');
    addQ(2, 10, 3, 'Ormanların yetişebildiği en yüksek sınırı (orman üst sınırı) belirleyen temel faktör nedir?', 'Sıcaklık (ve yükselti)', 'Yağış miktarı', 'Toprak türü', 'Rüzgarlar', 'İnsan etkisi', 'A', 'Orman alt sınırını nem ve yağış belirlerken, orman üst sınırını sıcaklık yetersizliği belirler.');
    addQ(2, 10, 3, 'Akdeniz Bölgesi\'nde orman üst sınırının (yaklaşık 2000-2200 m) Karadeniz\'den (1800 m) daha yüksek olmasının nedeni nedir?', 'Akdeniz\'in ekvatora daha yakın ve daha sıcak olması (Enlem etkisi)', 'Yağışın daha çok olması', 'Nem oranının yüksekliği', 'Rüzgar yönü', 'Toprak yapısı', 'A', 'Enlem gereği Akdeniz daha sıcaktır, ağaçlar daha yüksek rakımlarda bile yaşayabilir.');
    addQ(2, 10, 3, 'Geçmiş jeolojik dönemlerdeki iklim koşullarından günümüze kadar varlığını koruyabilmiş kalıntı bitkilere ne ad verilir?', 'Relikt Bitki', 'Endemik Bitki', 'Maki', 'Bozkır', 'Halofit', 'A', 'Relikt bitkiler buzul çağlarından kalan ve sığınak alanlarda yaşamını sürdüren kalıntı türlerdir.');
    addQ(2, 10, 3, 'Türkiye\'de donlu gün sayısının en az olduğu kıyılarımız hangisidir?', 'Akdeniz kıyıları (0-1 gün)', 'Karadeniz kıyıları', 'Marmara kıyıları', 'Ege kıyıları', 'İç Anadolu', 'A', 'Akdeniz kıyılarında kışlar çok ılık geçtiği için don olayı neredeyse hiç görülmez, seracılık çok gelişmiştir.');
    addQ(2, 10, 3, 'Türkiye\'de güneş enerjisinden yararlanma potansiyelinin en yüksek olduğu bölge hangisidir?', 'Güneydoğu Anadolu ve Akdeniz', 'Karadeniz', 'Marmara', 'Doğu Anadolu', 'İç Anadolu', 'A', 'Güneydoğu ve Akdeniz\'de bulutluluk az, güneşlenme süresi yıllık 3000 saatin üzerindedir.');
    addQ(2, 10, 3, 'Aşağıdaki akarsularımızdan hangisi açık havza özelliğinde olup enerjisi en yüksek akarsularımızdandır ve hidroelektrik potansiyeli en fazladır?', 'Fırat ve Dicle Nehirleri', 'Tuz Gölü Havzası', 'Van Gölü Kapalı Havzası', 'Burdur Havzası', 'Akarçay', 'A', 'Fırat nehri üzerindeki Keban, Karakaya ve Atatürk Barajları Türkiye\'nin elektrik üretim omurgasıdır.');
    addQ(2, 10, 3, 'Türkiye sınırları dışından doğup Türkiye topraklarından denize dökülen nehirler hangileridir?', 'Meriç ve Asi Nehirleri', 'Fırat ve Dicle', 'Aras ve Kura', 'Kızılırmak ve Yeşilırmak', 'Seyhan ve Ceyhan', 'A', 'Meriç Bulgaristan\'dan, Asi ise Lübnan/Suriye\'den doğup ülkemizden denize dökülür.');
    addQ(2, 10, 3, 'Türkiye sınırları içinden doğup komşu ülkelerden Hazar Denizi\'ne dökülen kapalı havza nehirlerimiz hangileridir?', 'Aras ve Kura Nehirleri', 'Fırat ve Dicle', 'Çoruh', 'Asi', 'Meriç', 'A', 'Aras ve Kura Doğu Anadolu\'dan doğarak Azerbaycan üzerinden Hazar Kapalı Havzası\'na dökülür.');

