    addQ(2, 11, 1, 'Cumhuriyet döneminde Türkiye\'de ilk genel nüfus sayımı hangi yılda yapılmıştır?', '1927', '1923', '1935', '1940', '1950', 'A', 'İlk nüfus sayımı 1927\'de yapılmış ve Türkiye nüfusu 13.6 milyon olarak tespit edilmiştir.');
    addQ(2, 11, 1, 'Türkiye\'de nüfus artış hızının tarihteki en düşük seviyeye gerilediği dönem hangi tarihi olayın yaşandığı yıllardır?', 'II. Dünya Savaşı yılları (1940-1945)', 'I. Dünya Savaşı', '1980 Askeri Darbesi', '1999 Depremi', '1974 Kıbrıs Barış Harekatı', 'A', 'Seferberlik ilanı ve erkeklerin silah altına alınması nedeniyle 1940-45 arası nüfus artış hızı binde 10.6\'ya inmiştir.');
    addQ(2, 11, 1, 'Türkiye\'de nüfusun ve sanayinin en yoğun olduğu coğrafi bölge hangisidir?', 'Marmara Bölgesi', 'Ege Bölgesi', 'İç Anadolu', 'Akdeniz', 'Karadeniz', 'A', 'İstanbul, Kocaeli, Bursa sanayi ve ticaret aksı nedeniyle Marmara nüfusun üçte birini barındırır.');
    addQ(2, 11, 1, 'Türkiye\'de aritmetik nüfus yoğunluğu en az olan ilimiz hangisidir?', 'Tunceli', 'Bayburt', 'Ardahan', 'Gümüşhane', 'Sinop', 'A', 'Yüzölçümüne düşen kişi sayısının en az olduğu il Tunceli\'dir.');
    addQ(2, 11, 1, 'Karadeniz Bölgesi\'nde arazinin aşırı dağınık ve engebeli, su kaynaklarının bol olması hangi kırsal yerleşme türünü doğurmuştur?', 'Dağınık Yerleşme', 'Toplu Yerleşme', 'Çizgisel Yerleşme', 'Dairesel Yerleşme', 'Kıyı Boyu Yerleşme', 'A', 'Karadeniz\'de evler birbirinden uzaktır (dağınık); İç Anadolu\'da ise su kuyusu etrafında toplu yerleşme görülür.');
    addQ(2, 11, 1, 'İç Anadolu ve Güneydoğu Anadolu\'da su kaynaklarının kıt, yer şekillerinin düz olması hangi yerleşme tipini zorunlu kılmıştır?', 'Toplu Yerleşme', 'Dağınık Yerleşme', 'Kıyı Yerleşmesi', 'Orman İçi Yerleşme', 'Dalgın Yerleşme', 'A', 'Su kaynaklarının sınırlı olduğu kurak bölgelerde köyler su kaynağı etrafında toplu kurulur.');
    addQ(2, 11, 1, 'Türkiye\'de nüfus artış hızının en yüksek olduğu (patlama yaptığı) dönem hangisidir?', '1955-1960 dönemi (Binde 28.5)', '1927-1935', '1940-1945', '2000-2005', '2015-2020', 'A', 'Savaş tehdidinin bitmesi, sağlık şartlarının iyileşmesiyle 1955-60 arası nüfus patlaması yaşanmıştır.');
    addQ(2, 11, 1, 'Türkiye\'de iç göçün en önemli ve belirleyici sebebi aşağıdakilerden hangisidir?', 'Ekonomik nedenler (İş imkanları ve sanayileşme)', 'Eğitim', 'Sağlık', 'Doğal afetler', 'Güvenlik', 'A', 'Kırsal alanda tarımda makineleşmeyle işsiz kalan nüfus sanayi kentlerine göç etmiştir.');
    addQ(2, 11, 1, 'Yaz mevsiminde tarım, inşaat veya turizm amacıyla başka şehirlere gidilip sonbaharda geri dönülen göç türüne ne ad verilir?', 'Mevsimlik (Geçici) Göç', 'Sürekli Göç', 'Mübadele Göçü', 'Beyin Göçü', 'Sığınmacı Göçü', 'A', 'Çukurova\'ya pamuk, Karadeniz\'e fındık, Akdeniz\'e turizm için giden işçiler mevsimlik göçmenlerdir.');
    addQ(2, 11, 1, 'Lozan Barış Antlaşması uyarınca Türkiye ile Yunanistan arasında gerçekleşen zorunlu nüfus değişimine ne ad verilir?', 'Etabli (Mübadele) Göçü', 'Beyin Göçü', 'İşçi Göçü', 'Mülteci Göçü', 'İltica', 'A', '1923 Türk-Yunan Mübadelesi ile Batı Trakya ve İstanbul hariç karşılıklı nüfus değişimi yapılmıştır.');

    // Level 2: Orta Düzey
    addQ(2, 11, 2, 'Aşağıdaki kırsal yerleşmelerden hangisi "köy altı geçici yerleşmeler" arasında yer alır?', 'Yayla, Kom, Ağıl, Oba, Dam', 'Divan, Mahalle, Çiftlik, Mezra', 'Kasaba', 'Belde', 'Köy', 'A', 'Yayla, kom, ağıl, oba hayvancılık amaçlı geçici yerleşmelerdir. Divan, mezra, mahalle, çiftlik ise süreklidir.');
    addQ(2, 11, 2, 'Batı Karadeniz\'e (Bolu, Sinop, Kastamonu) özgü olan, birkaç mahallenin bir araya gelmesiyle oluşan sürekli köy altı yerleşmesi hangisidir?', 'Divan', 'Mezra', 'Kom', 'Ağıl', 'Oba', 'A', 'Divan Batı Karadeniz\'de ormanlık alanlardaki sürekli köy altı yerleşmesidir.');
    addQ(2, 11, 2, 'Doğu Anadolu\'da yaygın olan, genellikle büyükbaş hayvancılık yapılan ve kışın terk edilen geçici yerleşmeye ne ad verilir?', 'Kom', 'Divan', 'Dalyan', 'Çiftlik', 'Mahalle', 'A', 'Kom Doğu Anadolu\'da taş binalı küçük hayvancılık yerleşmesidir.');
    addQ(2, 11, 2, 'Ege ve Akdeniz kıyılarında balık üretimi ve avcılığı amacıyla kurulan geçici kıyı yerleşmesine ne ad verilir?', 'Dalyan', 'Oba', 'Dam', 'Ağıl', 'Güzle', 'A', 'Dalyan deniz veya lagün kıyılarında kurulan balıkçılık yerleşmeleridir.');
    addQ(2, 11, 2, 'Tarımsal nüfus yoğunluğu tarımla uğraşan nüfusun tarım alanlarına bölünmesiyle bulunur. Aşağıdaki illerin hangisinde tarımsal nüfus yoğunluğu en fazladır?', 'Rize ve Hakkari', 'Konya', 'Şanlıurfa', 'Adana', 'Edirne', 'A', 'Tarım arazisi çok dar ve engebeli olduğu için Doğu Karadeniz ve Hakkari\'de tarımsal yoğunluk çok yüksektir.');
    addQ(2, 11, 2, 'Fizyolojik nüfus yoğunluğu toplam nüfusun tarım alanlarına bölünmesiyle bulunur. Türkiye\'de fizyolojik nüfus yoğunluğu nerede en yüksektir?', 'İstanbul ve Çatalca-Kocaeli', 'Konya', 'Sivas', 'Yozgat', 'Kars', 'A', 'İstanbul\'da toplam nüfus 16 milyonu aşarken tarım arazisi neredeyse yok denecek kadar azdır.');
    addQ(2, 11, 2, 'Türkiye\'de 65 yaş ve üzeri yaşlı nüfus oranının artması, ortanca yaşın yükselmesi neyin göstergesidir?', 'Nüfusun yaşlanmakta olduğunun ve gelişmişlik düzeyinin arttığının', 'Doğum oranlarının arttığının', 'Ölüm oranlarının patladığının', 'Eğitimin çöktüğünün', 'Tarıma dönüldüğünün', 'A', 'Sağlık koşullarının iyileşmesi ve ortalama ömrün uzamasıyla Türkiye demografik dönüşüm yaşamaktadır.');
    addQ(2, 11, 2, 'Aşağıdaki alanlardan hangisi Türkiye\'de yer şekillerinin engebeli veya karstik olması sebebiyle nüfus yoğunluğunun düşük olduğu yerlerden biridir?', 'Teke ve Taşeli Platoları ile Menteşe Yöresi', 'Çukurova', 'Kıyı Ege ovaları', 'Bursa Ovası', 'Adapazarı Ovası', 'A', 'Menteşe aşırı engebeli; Teke ve Taşeli ise karstik, çorak ve engebeli olduğu için nüfus tenhadır.');
    addQ(2, 11, 2, 'Türkiye\'de Adrese Dayalı Nüfus Kayıt Sistemi (ADNKS) hangi yıldan itibaren uygulanmaya başlanmıştır?', '2007', '1990', '2000', '1985', '2015', 'A', '2007 yılından itibaren sokağa çıkma yasaklı sayımlar terk edilmiş ve ADNKS\'ye geçilmiştir.');
    addQ(2, 11, 2, 'Türkiye\'nin yurt dışına ilk resmi kitlesel işçi göçü 1961 yılında hangi ülkeyle imzalanan anlaşmayla başlamıştır?', 'Almanya', 'Fransa', 'Avusturya', 'Hollanda', 'Belçika', 'A', '30 Ekim 1961\'de imzalanan Türk-Alman İşgücü Anlaşması ile yüz binlerce vatandaşımız Almanya\'ya gitmiştir.');

    // Level 3: Zor & Detay
    addQ(2, 11, 3, 'Tuz Gölü çevresi, Taşeli Platosu ve Yıldız Dağları\'nın nüfusunun seyrek olmasının ortak ve farklı sebepleri nelerdir?', 'Tuz Gölü kuraklık, Yıldız Dağları engebe ve ana yollara uzaklık, Taşeli karstik yapı', 'Hepsi engebedir', 'Hepsi sanayi bölgesidir', 'Hepsi maden bölgesidir', 'Hepsi heyelan alanıdır', 'A', 'Farklı coğrafi faktörler (iklim/kuraklık, litoloji/karstik, morfoloji/engebe) nüfusun tenhalaşmasına yol açar.');
    addQ(2, 11, 3, 'Büyükşehir statüsüne geçebilmek için bir ilin toplam nüfusunun en az ne kadar olması kanunen zorunludur?', '750.000', '500.000', '1.000.000', '250.000', '300.000', 'A', '5216 ve 6360 sayılı kanunlara göre büyükşehir belediyesi kurulması için toplam nüfusun en az 750 bin olması gerekir.');
    addQ(2, 11, 3, '6360 sayılı Büyükşehir Kanunu ile büyükşehir belediyesi olan illerde köy ve beldelerin tüzel kişiliği neye dönüştürülmüştür?', 'Mahalle', 'İlçe', 'Kasaba', 'Mezra', 'Bucak', 'A', 'Büyükşehir sınırları il mülki sınırı yapılmış, köyler mahalleye dönüştürülerek köy statüsü kaldırılmıştır.');
    addQ(2, 11, 3, 'Toros Dağları üzerinde konargöçer yaşayan Yörüklerin kıl çadırlardan oluşan geçici yerleşmelerine ne denir?', 'Oba', 'Kom', 'Divan', 'Ağıl', 'Çiftlik', 'A', 'Oba Yörük kültürünün geleneksel çadır yerleşmesidir.');
    addQ(2, 11, 3, 'Karadeniz\'de yayla yerleşmelerinin son yıllarda hayvancılık işlevinin yerini hangi ekonomik sektör almaya başlamıştır?', 'Eko-turizm ve yayla turizmi', 'Sanayi', 'Madencilik', 'Ticaret', 'Ormancılık', 'A', 'Ayder, Uzungöl gibi yaylalar yayla turizminin cazibe merkezine dönüşmüştür.');
    addQ(2, 11, 3, 'Türkiye nüfus piramidinin tabanının giderek daralması aşağıdakilerden hangisinin kesin kanıtıdır?', 'Doğum oranlarının azaldığının', 'Ölümlerin arttığının', 'Nüfusun azaldığının', 'Dış göç verildiğinin', 'Tarımın bittiğinin', 'A', 'Tabanın daralması 0-4 yaş çocuk sayısının azaldığını ve doğurganlığın düştüğünü gösterir.');
    addQ(2, 11, 3, 'Nüfus piramidinin üst kısmının (65+ yaş) genişlemesi neyi ifade eder?', 'Yaşam kalitesinin ve ortalama yaşam süresinin uzadığını', 'Savaş çıktığını', 'Genç nüfusun arttığını', 'İşsizliğin bittiğini', 'Emeklilik yaşının düştüğünü', 'A', 'Gelişmiş ülkelerdeki gibi yaşlı nüfus oranının artması sağlık ve refah koşullarının geliştiğini gösterir.');
    addQ(2, 11, 3, 'Türkiye\'de net göç hızı en yüksek olan ve sürekli dışarıdan nitelikli göç alan bölge hangisidir?', 'Marmara (Çatalca-Kocaeli alt bölgesi)', 'Doğu Anadolu', 'Güneydoğu Anadolu', 'Karadeniz', 'İç Anadolu', 'A', 'İş olanakları ve eğitim nedeniyle Marmara net göç hızında daima zirvededir.');
    addQ(2, 11, 3, 'Güneydoğu Anadolu Projesi (GAP) ile birlikte bölgeden batıya yapılan mevsimlik işçi göçünde nasıl bir değişim yaşanmıştır?', 'Sulu tarımla birlikte bölge içi istihdam artmış ve mevsimlik göç azalmıştır', 'Göç tamamen durmuştur', 'Dış göç patlamıştır', 'Göç iki katına çıkmıştır', 'Hiç değişmemiştir', 'A', 'GAP sulaması pamuk ve mısır üretimini Güneydoğu\'ya taşımış, işgücünü kendi bölgesinde tutmuştur.');
    addQ(2, 11, 3, 'İç Anadolu\'da kırsal meskenlerde yapı malzemesi olarak kerpiç, Karadeniz\'de ahşap, Akdeniz ve Güneydoğu\'da taş kullanılmasının temel nedeni nedir?', 'Doğal çevrede bulunan hakim yapı malzemesinin kullanılması', 'Kültürel zevkler', 'Deprem yönetmeliği', 'Gelir düzeyi', 'Padişah fermanları', 'A', 'Kırsal kesimde meskenler çevredeki doğal kaynaklara (orman varsa ahşap, kireçtaşı varsa taş, killi toprak varsa kerpiç) göre inşa edilir.');

    // -------------------------------------------------------------------------
    // Subcat 12: Türkiye Tarım, Hayvancılık ve Madenler
    // -------------------------------------------------------------------------
    // Level 1: Temel Ekonomik Coğrafya
    addQ(2, 12, 1, 'Türkiye\'de üretimi devlet kontrolünde olan, uyuşturucu yapımında kullanıldığı için izinle ekilen ürünler hangileridir?', 'Haşhaş ve Kenevir', 'Pamuk ve Mısır', 'Buğday ve Arpa', 'Çay ve Fındık', 'Zeytin ve Üzüm', 'A', 'Haşhaş (Afyon) ve Kenevir narkotik özellikleri nedeniyle TMO ve İçişleri izniyle ekilir.');
    addQ(2, 12, 1, 'Türkiye\'nin dünya üretiminde ve ihracatında açık ara birinci olduğu tarım ürünleri hangileridir?', 'Fındık, Kuru İncir, Kuru Kayısı, Kiraz', 'Buğday ve Pirinç', 'Muz ve Kahve', 'Pamuk ve Mısır', 'Soya ve Kakao', 'A', 'Türkiye fındık, incir, kayısı ve kiraz üretiminde dünya lideridir.');
    addQ(2, 12, 1, 'Türkiye\'de bozkır bitki örtüsünün yaygın olduğu İç Anadolu\'da en çok yapılan hayvancılık türü nedir?', 'Küçükbaş Hayvancılık (Koyun-Keçi)', 'Büyükbaş Hayvancılık', 'İpek Böcekçiliği', 'Kümes Hayvancılığı', 'Balıkçılık', 'A', 'Bozkır otları kısa boylu olduğu için küçükbaş koyun (özellikle Karaman koyunu) yetiştiriciliğine uygundur.');
    addQ(2, 12, 1, 'Erzurum-Kars platosunda yaz yağmurlarıyla yeşeren gür çayırlarda en yaygın yapılan hayvancılık faaliyeti nedir?', 'Büyükbaş Mera Hayvancılığı', 'Küçükbaş Koyunculuk', 'Tiftik Keçisi', 'Kıl Keçisi', 'Arıcılık', 'A', 'Gür alpin çayırlar sığır ve büyükbaş mera hayvancılığını geliştirmiştir.');
    addQ(2, 12, 1, 'Toros Dağları\'nın dik ve kayalık yamaçlarında makilerle beslenen, ormanlara zarar verdiği için sınırlandırılan keçi türü hangisidir?', 'Kıl Keçisi', 'Tiftik Keçisi (Ankara Keçisi)', 'Merinos Koyunu', 'Kıvırcık Koyun', 'Saanen Keçisi', 'A', 'Kıl keçisi Akdeniz Toroslarında yaygındır.');
    addQ(2, 12, 1, 'Dünya rezervlerinin yaklaşık %73\'ü Türkiye\'de bulunan, roket yakıtı, cam ve seramik sanayisinde kullanılan stratejik maden hangisidir?', 'Bor Mineralleri', 'Demir', 'Bakır', 'Krom', 'Boksit', 'A', 'Balıkesir Susurluk, Kütahya Emet, Eskişehir Kırka ve Bursa Mustafa Kemal Paşa\'da zengin bor yatakları vardır.');
    addQ(2, 12, 1, 'Türkiye\'de çıkarılan tek Taş Kömürü (I. Jeolojik Zaman / Paleozoyik kökenli) havzamız neresidir?', 'Zonguldak Havzası (Ereğli-Karabük)', 'Soma', 'Afşin-Elbistan', 'Yatağan', 'Tunçbilek', 'A', 'Taş kömürü sadece Zonguldak ve çevresindedir ve demir-çelik sanayisinde enerji kaynağı olarak kullanılır.');
    addQ(2, 12, 1, 'III. Jeolojik zamanda oluşan, kalorisi taş kömüründen düşük ancak Türkiye\'nin hemen her bölgesinde bolca bulunan kömür türü nedir?', 'Linyit Kömürü', 'Taş Kömürü', 'Antrasit', 'Kok Kömürü', 'Torf', 'A', 'Linyit yatakları termik santrallerimizde (Afşin-Elbistan, Soma, Yatağan) elektrik üretiminde kullanılır.');
    addQ(2, 12, 1, 'Türkiye\'nin ilk petrol kuyusu nerede açılmıştır ve en çok petrol çıkarılan ilimiz neresidir?', 'Batman (Raman Dağı)', 'Diyarbakır', 'Adıyaman', 'Siirt', 'Şırnak (Gabar)', 'A', '1940\'ta Raman Dağı\'nda petrol bulunmuş ve Batman Rafinerisi kurulmuştur.');
    addQ(2, 12, 1, 'Jeotermal enerji (yer altı sıcak su buharı) ile elektrik üreten santrallerimiz ilk olarak nerede kurulmuştur?', 'Denizli Sarayköy ve Aydın Germencik', 'İzmir Aliağa', 'Kocaeli Dilovası', 'Bursa Orhangazi', 'Afyon Sandıklı', 'A', 'Kırıklı fay hatlarının çok olduğu Ege Bölgesi jeotermal elektrik üretiminin merkezidir.');

    // Level 2: Orta Düzey
    addQ(2, 12, 2, 'Paslanmaz çelik yapımında kullanılan, Elazığ Guleman ve Muğla Fethiye-Köyceğiz\'de çıkarılan maden hangisidir?', 'Krom', 'Bakır', 'Boksit', 'Kurşun', 'Çinko', 'A', 'Krom paslanmaz çelik sanayisinin ana maddesidir. Antalya ve Elazığ\'da ferrokrom tesisleri vardır.');
    addQ(2, 12, 2, 'Alüminyumun hammaddesi olan ve Antalya Akseki ile Konya Seydişehir\'de çıkarılıp işlenen maden hangisidir?', 'Boksit', 'Barit', 'Mermer', 'Asbest', 'Kükürt', 'A', 'Seydişehir Alüminyum Fabrikası boksit madenini işler.');
    addQ(2, 12, 2, 'Elektrik-elektronik sanayisinde iletken olarak yaygın kullanılan, Artvin Murgul, Rize Çayeli ve Kastamonu Küre\'de çıkarılan maden hangisidir?', 'Bakır', 'Demir', 'Krom', 'Cıva', 'Antimon', 'A', 'Samsun Bakır İşletmeleri\'nde Karadeniz bakırları izabe edilir.');
    addQ(2, 12, 2, 'Petrol taşımacılığında petrol rafinerilerimiz hangi illerimizde yer almaktadır?', 'Batman, İzmir (Aliağa), Kocaeli (İpraş), Kırıkkale (Orta Anadolu)', 'Adana, Mersin', 'İstanbul, Ankara', 'Antalya, Samsun', 'Zonguldak, Trabzon', 'A', 'Batman hammaddenin yanında; İzmir ve İzmit liman avantajı; Kırıkkale ise stratejik iç güvenlik avantajıyla kurulmuştur.');
    addQ(2, 12, 2, 'Türkiye\'nin ilk nükleer güç santrali nerede inşa edilmektedir?', 'Mersin - Akkuyu', 'Sinop - İnceburun', 'Kırklareli - İğneada', 'İzmir - Çeşme', 'Balıkesir - Bandırma', 'A', 'Akkuyu Nükleer Güç Santrali 4 reaktörlü devasa bir nükleer projedir.');
    addQ(2, 12, 2, 'Türkiye\'de rüzgar enerjisi santrallerinin (RES) en çok yoğunlaştığı bölge hangisidir?', 'Ege ve Marmara (İzmir, Balıkesir, Çanakkale, Manisa)', 'Karadeniz', 'Doğu Anadolu', 'Güneydoğu Anadolu', 'İç Anadolu', 'A', 'Sürekli ve güçlü rüzgar alan Çanakkale Boğazı ve Ege kıyıları RES yatırımlarının merkezidir.');
    addQ(2, 12, 2, 'Demir-çelik fabrikalarının Karabük ve Ereğli\'de kurulmasının temel sebebi nedir?', 'Taş kömürü yataklarına (Enerji kaynağına) yakınlık', 'Demir madenine yakınlık', 'Pazara yakınlık', 'İşgücü ucuzluğu', 'Ulaşım kolaylığı', 'A', 'Karabük ve İskenderun örnekleri: Karabük enerjiye yakınlık, İskenderun ise liman (ulaşım) avantajıyla kurulmuştur.');
    addQ(2, 12, 2, 'GAP projesi sonrasında Güneydoğu Anadolu\'da üretimi katlanarak Türkiye birincisi haline gelen tarım ürünü hangisidir?', 'Pamuk', 'Çay', 'Fındık', 'Şeker Pancarı', 'Zeytin', 'A', 'Şanlıurfa Ovası sulamaya açılınca Çukurova\'yı geçerek Türkiye pamuk üretiminin yarısından fazlasını karşılar hale gelmiştir.');
    addQ(2, 12, 2, 'Güneşlenme süresinin yetersiz olması ve her mevsim yağışlı geçmesi sebebiyle Karadeniz kıyılarında üretimi yapılamayan ürün grubu hangisidir?', 'Pamuk ve Buğday (Yaz kuraklığı isteyenler)', 'Çay', 'Fındık', 'Mısır', 'Kivi', 'A', 'Pamuk ve buğday olgunlaşma ve hasat döneminde mutlaka kavurucu yaz kuraklığı ister; Karadeniz\'de yazın da yağış olduğu için yetişmez.');
    addQ(2, 12, 2, 'Türkiye\'de şeker fabrikalarının hammaddeye yakın yerlerde kurulmasının zorunlu olmasının sebebi nedir?', 'Şeker pancarının hasat edildikten sonra çok kısa sürede bozulması ve şeker oranının düşmesi', 'Nakliyesinin çok pahalı olması', 'İşçilerin tarlada yaşaması', 'Devlet teşviki', 'Su kaynakları', 'A', 'Şeker pancarı çabuk bozulduğu için fabrikalar pancar ekim sahalarının hemen yanına kurulur, küspesi de besi hayvancılığında kullanılır.');

    // Level 3: Zor & Detay
    addQ(2, 12, 3, 'Petrol ve doğalgaz sondaj kuyularında çamur ağırlaştırıcı olarak kullanılan, Alanya ve Gazipaşa\'da bolca çıkarılan maden hangisidir?', 'Barit', 'Mermer', 'Feldspat', 'Lüle Taşı', 'Oltu Taşı', 'A', 'Barit yüksek yoğunluğu nedeniyle sondaj çamurlarında basınç dengeleyici olarak kullanılır.');
    addQ(2, 12, 3, 'Eskişehir\'de çıkarılan süs eşyası ve pipo yapımında kullanılan beyaz renkli mineral ile Erzurum\'da çıkarılan siyah renkli kehribar taşları sırasıyla hangileridir?', 'Lüle Taşı (Eskişehir) - Oltu Taşı (Erzurum)', 'Mermer - Granit', 'Kuvars - Ametist', 'Oniks - Akik', 'Zümrüt - Yakut', 'A', 'Eskişehir Lüle taşı, Erzurum Oltu taşı el sanatları ve hediyelik eşya simgesidir.');
    addQ(2, 12, 3, 'Türkiye\'nin ihraç ettiği madenler içinde parasal gelir bakımından birinci sırada yer alan maden hangisidir?', 'İşlenmiş ve Blok Mermer (Doğal Taşlar)', 'Bor', 'Krom', 'Demir', 'Bakır', 'A', 'Afyon, Marmara Adası, Bilecik ve Elazığ mermerleri Türkiye\'nin maden ihracat şampiyonudur.');
    addQ(2, 12, 3, 'Nadas tarımının (toprağı bir yıl ekmeyip dinlendirme) en yaygın olduğu ve erozyonu tetiklediği bölge hangisidir?', 'İç Anadolu ve Güneydoğu Anadolu', 'Karadeniz', 'Akdeniz', 'Marmara', 'Kıyı Ege', 'A', 'Kuraklık ve sulama yetersizliği nedeniyle İç Anadolu\'da nadas çoktur; sulama geliştikçe nadas azalır.');
    addQ(2, 12, 3, 'Aşağıdaki tarım ürünlerinden hangisinin ekim alanı devlet tekelinde OLMAMASINA rağmen iklim seçiciliği yüzünden en dardır?', 'Çay ve Muz', 'Haşhaş', 'Tütün', 'Pirinç', 'Kenevir', 'A', 'Çay sadece Doğu Karadeniz kıyılarında, Muz sadece Akdeniz mikroklimasında yetişebilir.');
    addQ(2, 12, 3, 'Pirinç (çeltik) üretim alanlarının devlet iznine ve kontrolüne tabi olmasının gerçek halk sağlığı gerekçesi nedir?', 'Sıtma hastalığına yol açan sivrisinek üremesini engellemek', 'Uyuşturucu yapımı', 'Toprağı tuzlandırması', 'Pahalı olması', 'Kota uygulaması', 'A', 'Çeltik bataklık suda yetiştiği için sivrisinek üremesini ve sıtma salgınını önlemek amacıyla yerleşim yerlerinden uzağa izinle ekilir.');
    addQ(2, 12, 3, 'Türkiye\'de arıcılık faaliyetlerinin ve bal üretiminin en kaliteli ve yaygın olduğu dağlık ve zengin bitki örtülü illerimiz hangileridir?', 'Muğla (Çam balı), Ordu, Rize (Anzer), Hakkari, Kars', 'Konya ve Aksaray', 'Edirne ve Tekirdağ', 'Şanlıurfa', 'Gaziantep', 'A', 'Muğla çam balında dünya merkezidir; Ordu, Rize ve Doğu Anadolu yaylaları çiçek balında öncüdür.');
    addQ(2, 12, 3, 'Büyükşehirlerin etrafında (İstanbul, Ankara, İzmir, Bolu, Balıkesir) besi ve kümes hayvancılığının aşırı gelişmiş olmasının temel nedeni nedir?', 'Tüketici nüfusun fazlalığı ve hızlı pazarlama imkanı (Pazara yakınlık)', 'İklimin uygunluğu', 'Yem bitkilerinin çokluğu', 'Geniş meraların varlığı', 'Su kaynakları', 'A', 'Besi ve kümes hayvancılığı iklime bağımlı değildir; kapalı çiftliklerde büyük kentlerin günlük et ve yumurta ihtiyacını karşılar.');
    addQ(2, 12, 3, 'Deniz balıkçılığında Türkiye toplam balık avının yaklaşık %75\'ini tek başına karşılayan denizimiz hangisidir?', 'Karadeniz', 'Marmara Denizi', 'Ege Denizi', 'Akdeniz', 'Van Gölü', 'A', 'Karadeniz besin maddesi (plankton) zenginliği ve oksijen bolluğu nedeniyle en çok balık avlanan denizimizdir.');
